#!/usr/bin/env python3
"""Add configurable Reward Chests to the wallet dashboard.

Target: git101815/mediacms, branch advanced-monetisation, after the Daily
Rewards feature (ledger migration 0035).

Run from the repository root:
    python apply_reward_chests_feature.py
"""

from __future__ import annotations

import hashlib
from pathlib import Path

ROOT = Path.cwd()


def fail(message: str) -> None:
    raise SystemExit(message)


def read(path: str) -> str:
    target = ROOT / path
    if not target.exists():
        fail(f"Missing expected repository file: {path}")
    return target.read_text(encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")


def git_blob_sha(content: str) -> str:
    raw = content.encode("utf-8")
    return hashlib.sha1(f"blob {len(raw)}\0".encode("ascii") + raw).hexdigest()


def replace_file(path: str, expected_old_sha: str, new_content: str) -> None:
    current = read(path)
    if current == new_content:
        return
    current_sha = git_blob_sha(current)
    if current_sha != expected_old_sha:
        fail(
            f"Refusing to overwrite modified file {path}: "
            f"expected blob {expected_old_sha}, found {current_sha}"
        )
    write(path, new_content)


def write_new(path: str, content: str) -> None:
    target = ROOT / path
    if target.exists():
        current = target.read_text(encoding="utf-8")
        if current == content:
            return
        fail(f"Refusing to overwrite existing file with different content: {path}")
    write(path, content)


def replace_once(path: str, old: str, new: str) -> None:
    content = read(path)
    if new in content:
        return
    count = content.count(old)
    if count != 1:
        fail(f"Expected exactly one patch context in {path}, found {count}")
    write(path, content.replace(old, new, 1))

replace_file('ledger/dashboard/config.py', '94f5525ff0a9a2f3675850d91119f5f5c5b6b093', '"""Editable economy configuration for the wallet dashboard.\n\nAmounts in this file are HUMAN token amounts. The accounting layer converts\nall values to the ledger\'s 6-decimal base unit before posting transactions.\n\nReward Chest drop probabilities use basis points: 10_000 bps = 100%.\nEvery chest\'s ``chance_bps`` values must add up to exactly 10_000.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nimport hashlib\nimport json\nimport re\nfrom typing import Iterable\n\nfrom django.core.exceptions import ImproperlyConfigured\n\n\nPLATFORM_TOKEN_DECIMALS = 6\n\n# ---------------------------------------------------------------------------\n# Generic Reward Chests\n# ---------------------------------------------------------------------------\nREWARD_CHEST_CONFIG_VERSION = 1\nREWARD_CHEST_TOTAL_CHANCE_BPS = 10_000\nREWARD_CHEST_MAX_DROPS = 100\nREWARD_CHEST_MAX_TOKENS_PER_DROP = 100_000\nREWARD_CHEST_MAX_EXPECTED_VALUE_TOKENS = 20_000\n_REWARD_CHEST_ABSOLUTE_MAX_DROPS = 1_000\n_LEDGER_MAX_HUMAN_TOKENS = ((2 ** 63) - 1) // (10 ** PLATFORM_TOKEN_DECIMALS)\n\n# ``asset`` accepts "chest" or "bigchest" and only controls the existing UI\n# illustration. ``drops`` are evaluated from top to bottom with a secure,\n# server-side roll in [0, 9_999].\nREWARD_CHESTS = {\n    "daily_standard": {\n        "label": "Daily Reward Chest",\n        "asset": "chest",\n        "drops": (\n            {"key": "common_100", "label": "100 tokens", "rarity": "common", "chance_bps": 5_500, "amount": 100},\n            {"key": "uncommon_250", "label": "250 tokens", "rarity": "uncommon", "chance_bps": 3_000, "amount": 250},\n            {"key": "rare_500", "label": "500 tokens", "rarity": "rare", "chance_bps": 1_200, "amount": 500},\n            {"key": "epic_1000", "label": "1,000 tokens", "rarity": "epic", "chance_bps": 280, "amount": 1_000},\n            {"key": "jackpot_5000", "label": "5,000 tokens", "rarity": "jackpot", "chance_bps": 20, "amount": 5_000},\n        ),\n    },\n    "daily_mega": {\n        "label": "Mega Reward Chest",\n        "asset": "bigchest",\n        "drops": (\n            {"key": "common_350", "label": "350 tokens", "rarity": "common", "chance_bps": 5_000, "amount": 350},\n            {"key": "uncommon_750", "label": "750 tokens", "rarity": "uncommon", "chance_bps": 3_000, "amount": 750},\n            {"key": "rare_1500", "label": "1,500 tokens", "rarity": "rare", "chance_bps": 1_500, "amount": 1_500},\n            {"key": "epic_3000", "label": "3,000 tokens", "rarity": "epic", "chance_bps": 450, "amount": 3_000},\n            {"key": "jackpot_10000", "label": "10,000 tokens", "rarity": "jackpot", "chance_bps": 50, "amount": 10_000},\n        ),\n    },\n}\n\n# ---------------------------------------------------------------------------\n# Daily Rewards\n# ---------------------------------------------------------------------------\nDAILY_REWARD_CONFIG_VERSION = 2\nDAILY_REWARDS_ENABLED = True\n\n# None means: use django.conf.settings.TIME_ZONE.\nDAILY_REWARD_TIME_ZONE = None\n\n# Number of cards shown in the compact dashboard widget.\nDAILY_REWARD_WINDOW_SIZE = 5\n\n# Hard guard against an accidental economy-breaking fixed reward.\nDAILY_REWARD_MAX_TOKENS_PER_CLAIM = 100_000\n\n# Fixed reward:\n#   {"kind": "fixed", "amount": 100, "asset": "coins"}\n# Reward Chest:\n#   {"kind": "chest", "chest": "daily_standard"}\n# Rows without ``kind`` remain backward-compatible and are treated as fixed.\nDAILY_REWARDS = (\n    {"kind": "fixed", "amount": 50, "asset": "coins"},\n    {"kind": "fixed", "amount": 75, "asset": "coins"},\n    {"kind": "fixed", "amount": 100, "asset": "coins"},\n    {"kind": "fixed", "amount": 125, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_standard"},\n    {"kind": "fixed", "amount": 200, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_mega"},\n    {"kind": "fixed", "amount": 75, "asset": "coins"},\n    {"kind": "fixed", "amount": 100, "asset": "coins"},\n    {"kind": "fixed", "amount": 100, "asset": "coins"},\n    {"kind": "fixed", "amount": 150, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_standard"},\n    {"kind": "fixed", "amount": 400, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_mega"},\n    {"kind": "fixed", "amount": 100, "asset": "coins"},\n    {"kind": "fixed", "amount": 125, "asset": "coins"},\n    {"kind": "fixed", "amount": 150, "asset": "coins"},\n    {"kind": "fixed", "amount": 200, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_standard"},\n    {"kind": "fixed", "amount": 350, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_mega"},\n    {"kind": "fixed", "amount": 150, "asset": "coins"},\n    {"kind": "fixed", "amount": 175, "asset": "coins"},\n    {"kind": "fixed", "amount": 200, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_standard"},\n    {"kind": "fixed", "amount": 300, "asset": "coins"},\n    {"kind": "fixed", "amount": 450, "asset": "coins"},\n    {"kind": "chest", "chest": "daily_mega"},\n    {"kind": "chest", "chest": "daily_standard"},\n    {"kind": "chest", "chest": "daily_mega"},\n)\n\n\n_ALLOWED_DAILY_ASSETS = frozenset({"coins", "chest", "bigchest"})\n_ALLOWED_CHEST_ASSETS = frozenset({"chest", "bigchest"})\n_IDENTIFIER_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,63}$")\n\n\n@dataclass(frozen=True)\nclass RewardChestDropDefinition:\n    key: str\n    label: str\n    rarity: str\n    chance_bps: int\n    amount_tokens: int\n    amount_units: int\n    cumulative_end_bps: int\n\n\n@dataclass(frozen=True)\nclass RewardChestDefinition:\n    key: str\n    label: str\n    asset: str\n    drops: tuple[RewardChestDropDefinition, ...]\n    min_amount_tokens: int\n    max_amount_tokens: int\n    expected_value_numerator: int\n\n    @property\n    def expected_value_tokens(self) -> float:\n        return self.expected_value_numerator / REWARD_CHEST_TOTAL_CHANCE_BPS\n\n\n@dataclass(frozen=True)\nclass DailyRewardDefinition:\n    day: int\n    kind: str\n    asset: str\n    amount_tokens: int | None\n    amount_units: int | None\n    chest_key: str\n    chest_label: str\n    min_amount_tokens: int\n    max_amount_tokens: int\n\n\ndef _require_whole_positive_int(value, *, field_name: str, maximum: int) -> int:\n    if isinstance(value, bool) or not isinstance(value, int):\n        raise ImproperlyConfigured(f"{field_name} must be a whole integer")\n    if value <= 0:\n        raise ImproperlyConfigured(f"{field_name} must be positive")\n    if value > maximum:\n        raise ImproperlyConfigured(f"{field_name} exceeds the configured safety maximum")\n    return value\n\n\ndef tokens_to_units(amount_tokens: int) -> int:\n    normalized = _require_whole_positive_int(\n        amount_tokens,\n        field_name="Reward amount",\n        maximum=max(\n            int(DAILY_REWARD_MAX_TOKENS_PER_CLAIM),\n            int(REWARD_CHEST_MAX_TOKENS_PER_DROP),\n        ),\n    )\n    return normalized * (10 ** PLATFORM_TOKEN_DECIMALS)\n\n\ndef _normalize_identifier(value, *, field_name: str) -> str:\n    normalized = str(value or "").strip().lower()\n    if not _IDENTIFIER_RE.fullmatch(normalized):\n        raise ImproperlyConfigured(\n            f"{field_name} must use lowercase letters, digits, underscores, or hyphens"\n        )\n    return normalized\n\n\ndef _normalize_reward_chest_definition(\n    key: str,\n    raw: dict,\n    *,\n    enforce_economy_limits: bool = True,\n) -> RewardChestDefinition:\n    key = _normalize_identifier(key, field_name="Reward Chest key")\n    if not isinstance(raw, dict):\n        raise ImproperlyConfigured(f"Reward Chest {key} must be a dictionary")\n\n    label = str(raw.get("label") or "").strip()\n    if not label or len(label) > 80:\n        raise ImproperlyConfigured(f"Reward Chest {key} requires a label of at most 80 characters")\n\n    asset = str(raw.get("asset") or "").strip().lower()\n    if asset not in _ALLOWED_CHEST_ASSETS:\n        raise ImproperlyConfigured(f"Reward Chest {key} has an invalid asset: {asset or \'<empty>\'}")\n\n    raw_drops = raw.get("drops")\n    if not isinstance(raw_drops, (list, tuple)) or not raw_drops:\n        raise ImproperlyConfigured(f"Reward Chest {key} must contain at least one drop")\n    maximum_drops = (\n        int(REWARD_CHEST_MAX_DROPS)\n        if enforce_economy_limits\n        else _REWARD_CHEST_ABSOLUTE_MAX_DROPS\n    )\n    if len(raw_drops) > maximum_drops:\n        raise ImproperlyConfigured(f"Reward Chest {key} contains too many drops")\n\n    drops = []\n    seen_drop_keys = set()\n    cumulative = 0\n    expected_value_numerator = 0\n\n    for index, raw_drop in enumerate(raw_drops, start=1):\n        if not isinstance(raw_drop, dict):\n            raise ImproperlyConfigured(f"Reward Chest {key} drop {index} must be a dictionary")\n\n        drop_key = _normalize_identifier(\n            raw_drop.get("key"),\n            field_name=f"Reward Chest {key} drop key",\n        )\n        if drop_key in seen_drop_keys:\n            raise ImproperlyConfigured(f"Reward Chest {key} contains duplicate drop key {drop_key}")\n        seen_drop_keys.add(drop_key)\n\n        chance_bps = _require_whole_positive_int(\n            raw_drop.get("chance_bps"),\n            field_name=f"Reward Chest {key} drop {drop_key} chance_bps",\n            maximum=REWARD_CHEST_TOTAL_CHANCE_BPS,\n        )\n        amount_tokens = _require_whole_positive_int(\n            raw_drop.get("amount"),\n            field_name=f"Reward Chest {key} drop {drop_key} amount",\n            maximum=(\n                REWARD_CHEST_MAX_TOKENS_PER_DROP\n                if enforce_economy_limits\n                else _LEDGER_MAX_HUMAN_TOKENS\n            ),\n        )\n        label_value = str(raw_drop.get("label") or f"{amount_tokens:,} tokens").strip()\n        if not label_value or len(label_value) > 80:\n            raise ImproperlyConfigured(f"Reward Chest {key} drop {drop_key} has an invalid label")\n        rarity = _normalize_identifier(\n            raw_drop.get("rarity") or "common",\n            field_name=f"Reward Chest {key} drop {drop_key} rarity",\n        )\n\n        cumulative += chance_bps\n        expected_value_numerator += amount_tokens * chance_bps\n        drops.append(\n            RewardChestDropDefinition(\n                key=drop_key,\n                label=label_value,\n                rarity=rarity,\n                chance_bps=chance_bps,\n                amount_tokens=amount_tokens,\n                amount_units=amount_tokens * (10 ** PLATFORM_TOKEN_DECIMALS),\n                cumulative_end_bps=cumulative,\n            )\n        )\n\n    if cumulative != REWARD_CHEST_TOTAL_CHANCE_BPS:\n        raise ImproperlyConfigured(\n            f"Reward Chest {key} drop rates must total exactly "\n            f"{REWARD_CHEST_TOTAL_CHANCE_BPS} bps, got {cumulative}"\n        )\n\n    max_expected_numerator = (\n        int(REWARD_CHEST_MAX_EXPECTED_VALUE_TOKENS)\n        * REWARD_CHEST_TOTAL_CHANCE_BPS\n    )\n    if enforce_economy_limits and expected_value_numerator > max_expected_numerator:\n        raise ImproperlyConfigured(\n            f"Reward Chest {key} expected value exceeds "\n            "REWARD_CHEST_MAX_EXPECTED_VALUE_TOKENS"\n        )\n\n    amounts = [drop.amount_tokens for drop in drops]\n    return RewardChestDefinition(\n        key=key,\n        label=label,\n        asset=asset,\n        drops=tuple(drops),\n        min_amount_tokens=min(amounts),\n        max_amount_tokens=max(amounts),\n        expected_value_numerator=expected_value_numerator,\n    )\n\n\ndef get_reward_chest_definitions() -> dict[str, RewardChestDefinition]:\n    if not isinstance(REWARD_CHESTS, dict):\n        raise ImproperlyConfigured("REWARD_CHESTS must be a dictionary")\n    normalized = {}\n    for raw_key, raw_definition in REWARD_CHESTS.items():\n        definition = _normalize_reward_chest_definition(raw_key, raw_definition)\n        if definition.key in normalized:\n            raise ImproperlyConfigured(f"Duplicate Reward Chest key: {definition.key}")\n        normalized[definition.key] = definition\n    return normalized\n\n\ndef get_reward_chest_definition(chest_key: str) -> RewardChestDefinition:\n    normalized_key = _normalize_identifier(chest_key, field_name="Reward Chest key")\n    definition = get_reward_chest_definitions().get(normalized_key)\n    if definition is None:\n        raise ImproperlyConfigured(f"Unknown Reward Chest: {normalized_key}")\n    return definition\n\n\ndef build_reward_chest_snapshot(definition: RewardChestDefinition) -> dict:\n    payload = {\n        "config_version": int(REWARD_CHEST_CONFIG_VERSION),\n        "key": definition.key,\n        "label": definition.label,\n        "asset": definition.asset,\n        "drops": [\n            {\n                "key": drop.key,\n                "label": drop.label,\n                "rarity": drop.rarity,\n                "chance_bps": int(drop.chance_bps),\n                "amount": int(drop.amount_tokens),\n            }\n            for drop in definition.drops\n        ],\n    }\n    canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)\n    payload["fingerprint"] = hashlib.sha256(canonical.encode("utf-8")).hexdigest()\n    return payload\n\n\ndef reward_chest_definition_from_snapshot(snapshot: dict) -> RewardChestDefinition:\n    if not isinstance(snapshot, dict):\n        raise ImproperlyConfigured("Reward Chest snapshot must be a dictionary")\n    fingerprint = str(snapshot.get("fingerprint") or "").strip().lower()\n    if len(fingerprint) != 64:\n        raise ImproperlyConfigured("Reward Chest snapshot fingerprint is missing")\n\n    payload = {\n        "config_version": snapshot.get("config_version"),\n        "key": snapshot.get("key"),\n        "label": snapshot.get("label"),\n        "asset": snapshot.get("asset"),\n        "drops": snapshot.get("drops"),\n    }\n    canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)\n    expected = hashlib.sha256(canonical.encode("utf-8")).hexdigest()\n    if expected != fingerprint:\n        raise ImproperlyConfigured("Reward Chest snapshot fingerprint does not match")\n\n    return _normalize_reward_chest_definition(\n        str(payload.get("key") or ""),\n        {\n            "label": payload.get("label"),\n            "asset": payload.get("asset"),\n            "drops": payload.get("drops"),\n        },\n        enforce_economy_limits=False,\n    )\n\n\ndef _normalize_reward_rows(rows: Iterable[dict]) -> tuple[DailyRewardDefinition, ...]:\n    chest_definitions = get_reward_chest_definitions()\n    normalized = []\n\n    for index, raw in enumerate(rows, start=1):\n        if not isinstance(raw, dict):\n            raise ImproperlyConfigured("Every DAILY_REWARDS item must be a dictionary")\n\n        raw_kind = str(raw.get("kind") or "").strip().lower()\n        kind = raw_kind or ("chest" if raw.get("chest") else "fixed")\n\n        if kind == "fixed":\n            amount_tokens = _require_whole_positive_int(\n                raw.get("amount"),\n                field_name=f"Daily reward amount on day {index}",\n                maximum=DAILY_REWARD_MAX_TOKENS_PER_CLAIM,\n            )\n            asset = str(raw.get("asset") or "").strip().lower()\n            if asset not in _ALLOWED_DAILY_ASSETS:\n                raise ImproperlyConfigured(\n                    f"Invalid daily reward asset on day {index}: {asset or \'<empty>\'}"\n                )\n            normalized.append(\n                DailyRewardDefinition(\n                    day=index,\n                    kind="fixed",\n                    asset=asset,\n                    amount_tokens=amount_tokens,\n                    amount_units=amount_tokens * (10 ** PLATFORM_TOKEN_DECIMALS),\n                    chest_key="",\n                    chest_label="",\n                    min_amount_tokens=amount_tokens,\n                    max_amount_tokens=amount_tokens,\n                )\n            )\n            continue\n\n        if kind == "chest":\n            if raw.get("amount") not in (None, ""):\n                raise ImproperlyConfigured(\n                    f"Daily reward day {index} cannot define both a chest and a fixed amount"\n                )\n            chest_key = _normalize_identifier(\n                raw.get("chest"),\n                field_name=f"Daily reward chest on day {index}",\n            )\n            chest = chest_definitions.get(chest_key)\n            if chest is None:\n                raise ImproperlyConfigured(\n                    f"Daily reward day {index} references unknown Reward Chest {chest_key}"\n                )\n            normalized.append(\n                DailyRewardDefinition(\n                    day=index,\n                    kind="chest",\n                    asset=chest.asset,\n                    amount_tokens=None,\n                    amount_units=None,\n                    chest_key=chest.key,\n                    chest_label=chest.label,\n                    min_amount_tokens=chest.min_amount_tokens,\n                    max_amount_tokens=chest.max_amount_tokens,\n                )\n            )\n            continue\n\n        raise ImproperlyConfigured(\n            f"Invalid daily reward kind on day {index}: {kind or \'<empty>\'}"\n        )\n\n    if not normalized:\n        raise ImproperlyConfigured("DAILY_REWARDS must contain at least one reward")\n\n    window_size = int(DAILY_REWARD_WINDOW_SIZE)\n    if window_size <= 0:\n        raise ImproperlyConfigured("DAILY_REWARD_WINDOW_SIZE must be positive")\n    if window_size > len(normalized):\n        raise ImproperlyConfigured(\n            "DAILY_REWARD_WINDOW_SIZE cannot exceed the reward cycle length"\n        )\n\n    return tuple(normalized)\n\n\ndef get_daily_reward_definitions() -> tuple[DailyRewardDefinition, ...]:\n    return _normalize_reward_rows(DAILY_REWARDS)\n')

replace_file('ledger/dashboard/models.py', '7aedd670f6d0be1512ff45f95151bbdee6e5b85f', 'import uuid\n\nfrom django.conf import settings\nfrom django.db import models\nfrom django.db.models import Q\n\n\nclass RewardChestGrant(models.Model):\n    STATUS_PENDING = "pending"\n    STATUS_OPENED = "opened"\n    STATUS_REVOKED = "revoked"\n    STATUS_CHOICES = (\n        (STATUS_PENDING, "Pending"),\n        (STATUS_OPENED, "Opened"),\n        (STATUS_REVOKED, "Revoked"),\n    )\n\n    public_id = models.UUIDField(\n        default=uuid.uuid4,\n        unique=True,\n        editable=False,\n        db_index=True,\n    )\n    user = models.ForeignKey(\n        settings.AUTH_USER_MODEL,\n        on_delete=models.PROTECT,\n        related_name="reward_chest_grants",\n    )\n    chest_key = models.CharField(max_length=64, db_index=True)\n    source_type = models.CharField(max_length=32, db_index=True)\n    source_ref = models.CharField(max_length=160)\n    status = models.CharField(\n        max_length=16,\n        choices=STATUS_CHOICES,\n        default=STATUS_PENDING,\n        db_index=True,\n    )\n\n    config_version = models.PositiveIntegerField()\n    config_snapshot = models.JSONField(default=dict)\n    metadata = models.JSONField(default=dict, blank=True)\n\n    roll = models.PositiveSmallIntegerField(null=True, blank=True)\n    drop_key = models.CharField(max_length=64, blank=True, default="")\n    drop_label = models.CharField(max_length=80, blank=True, default="")\n    rarity = models.CharField(max_length=64, blank=True, default="")\n    chance_bps = models.PositiveIntegerField(null=True, blank=True)\n    amount = models.BigIntegerField(null=True, blank=True)\n    ledger_txn = models.OneToOneField(\n        "ledger.LedgerTransaction",\n        on_delete=models.PROTECT,\n        related_name="reward_chest_grant",\n        null=True,\n        blank=True,\n    )\n\n    expires_at = models.DateTimeField(null=True, blank=True, db_index=True)\n    granted_at = models.DateTimeField(auto_now_add=True, db_index=True)\n    opened_at = models.DateTimeField(null=True, blank=True, db_index=True)\n    revoked_at = models.DateTimeField(null=True, blank=True)\n\n    class Meta:\n        ordering = ["-granted_at", "-id"]\n        constraints = [\n            models.UniqueConstraint(\n                fields=["source_type", "source_ref"],\n                name="unique_reward_chest_source_ref",\n            ),\n            models.CheckConstraint(\n                condition=Q(amount__isnull=True) | Q(amount__gt=0),\n                name="reward_chest_amount_positive_if_set",\n            ),\n            models.CheckConstraint(\n                condition=Q(roll__isnull=True) | (Q(roll__gte=0) & Q(roll__lt=10_000)),\n                name="reward_chest_roll_in_range",\n            ),\n            models.CheckConstraint(\n                condition=Q(chance_bps__isnull=True)\n                | (Q(chance_bps__gt=0) & Q(chance_bps__lte=10_000)),\n                name="reward_chest_chance_in_range",\n            ),\n        ]\n        indexes = [\n            models.Index(\n                fields=["user", "status", "-granted_at"],\n                name="ledger_chest_user_status_idx",\n            ),\n            models.Index(\n                fields=["chest_key", "status"],\n                name="ledger_chest_key_status_idx",\n            ),\n        ]\n\n    def __str__(self):\n        return f"Reward Chest {self.chest_key} for user {self.user_id} [{self.status}]"\n\n\nclass DailyRewardState(models.Model):\n    user = models.OneToOneField(\n        settings.AUTH_USER_MODEL,\n        on_delete=models.CASCADE,\n        related_name="daily_reward_state",\n    )\n    current_streak = models.PositiveIntegerField(default=0)\n    total_claims = models.PositiveIntegerField(default=0)\n    last_claim_date = models.DateField(null=True, blank=True)\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        constraints = [\n            models.CheckConstraint(\n                condition=Q(current_streak__gte=0),\n                name="daily_reward_state_streak_nonnegative",\n            ),\n            models.CheckConstraint(\n                condition=Q(total_claims__gte=0),\n                name="daily_reward_state_claims_nonnegative",\n            ),\n        ]\n\n    def __str__(self):\n        return f"Daily rewards for user {self.user_id}"\n\n\nclass DailyRewardClaim(models.Model):\n    user = models.ForeignKey(\n        settings.AUTH_USER_MODEL,\n        on_delete=models.PROTECT,\n        related_name="daily_reward_claims",\n    )\n    reward_date = models.DateField()\n    streak_day = models.PositiveIntegerField()\n    cycle_day = models.PositiveIntegerField()\n    amount = models.BigIntegerField()\n    ledger_txn = models.OneToOneField(\n        "ledger.LedgerTransaction",\n        on_delete=models.PROTECT,\n        related_name="daily_reward_claim",\n    )\n    reward_chest_grant = models.OneToOneField(\n        RewardChestGrant,\n        on_delete=models.PROTECT,\n        related_name="daily_reward_claim",\n        null=True,\n        blank=True,\n    )\n    config_version = models.PositiveIntegerField()\n    config_snapshot = models.JSONField(default=dict)\n    claimed_at = models.DateTimeField(auto_now_add=True)\n\n    class Meta:\n        ordering = ["-reward_date", "-id"]\n        constraints = [\n            models.UniqueConstraint(\n                fields=["user", "reward_date"],\n                name="unique_daily_reward_claim_per_user_day",\n            ),\n            models.CheckConstraint(\n                condition=Q(streak_day__gt=0),\n                name="daily_reward_claim_streak_positive",\n            ),\n            models.CheckConstraint(\n                condition=Q(cycle_day__gt=0),\n                name="daily_reward_claim_cycle_positive",\n            ),\n            models.CheckConstraint(\n                condition=Q(amount__gt=0),\n                name="daily_reward_claim_amount_positive",\n            ),\n        ]\n        indexes = [\n            models.Index(\n                fields=["user", "-claimed_at"],\n                name="ledger_daily_user_claim_idx",\n            ),\n        ]\n\n    def __str__(self):\n        return f"Daily reward {self.reward_date} for user {self.user_id}"\n')

replace_file('ledger/dashboard/daily_rewards.py', '96c8978d900907718f97e6a7a9cdf83ea2c80b05', 'from __future__ import annotations\n\nimport hashlib\nimport json\nfrom datetime import datetime, time, timedelta, timezone as datetime_timezone\nfrom zoneinfo import ZoneInfo, ZoneInfoNotFoundError\n\nfrom django.conf import settings\nfrom django.contrib.auth import get_user_model\nfrom django.core.exceptions import ImproperlyConfigured, PermissionDenied, ValidationError\nfrom django.db import transaction\nfrom django.utils import timezone\n\nfrom ledger.models import (\n    LEDGER_METADATA_VERSION,\n    LEDGER_RISK_STATUS_BLOCKED,\n    LEDGER_RISK_STATUS_REVIEW,\n    LedgerEntry,\n    LedgerOutbox,\n    LedgerTransaction,\n    TokenWallet,\n)\n\nfrom . import config\nfrom .models import DailyRewardClaim, DailyRewardState\nfrom .reward_chests import grant_reward_chest, open_reward_chest\n\n\nDAILY_REWARD_TRANSACTION_KIND = "daily_reward"\nDAILY_REWARD_OUTBOX_TOPIC = "ledger.daily_reward.claimed"\n\n_ASSET_IMAGE_PATHS = {\n    "coins": "images/wallet/dashboard/reward-coins.png",\n    "chest": "images/wallet/dashboard/reward-chest.png",\n    "bigchest": "images/wallet/dashboard/reward-bigchest.png",\n}\n\n\ndef _require_eligible_user(user):\n    if not getattr(user, "is_authenticated", False):\n        raise PermissionDenied("Authentication is required")\n    if not getattr(user, "pk", None):\n        raise PermissionDenied("A persisted user account is required")\n    if not getattr(user, "is_active", False):\n        raise PermissionDenied("Inactive accounts cannot claim daily rewards")\n    return user\n\n\ndef get_daily_reward_timezone() -> ZoneInfo:\n    timezone_name = (\n        config.DAILY_REWARD_TIME_ZONE\n        or getattr(settings, "TIME_ZONE", "UTC")\n        or "UTC"\n    )\n    try:\n        return ZoneInfo(str(timezone_name))\n    except ZoneInfoNotFoundError as exc:\n        raise ImproperlyConfigured(\n            f"Unknown DAILY_REWARD_TIME_ZONE: {timezone_name}"\n        ) from exc\n\n\ndef _normalize_instant(at=None):\n    instant = at or timezone.now()\n    if timezone.is_naive(instant):\n        instant = instant.replace(tzinfo=datetime_timezone.utc)\n    return instant\n\n\ndef get_daily_reward_date(at=None):\n    return _normalize_instant(at).astimezone(get_daily_reward_timezone()).date()\n\n\ndef get_next_daily_reward_reset(at=None):\n    instant = _normalize_instant(at)\n    reward_timezone = get_daily_reward_timezone()\n    local_instant = instant.astimezone(reward_timezone)\n    next_day = local_instant.date() + timedelta(days=1)\n    return datetime.combine(next_day, time.min, tzinfo=reward_timezone)\n\n\ndef _get_cycle_day(streak_day: int, cycle_length: int) -> int:\n    return ((int(streak_day) - 1) % int(cycle_length)) + 1\n\n\ndef _calculate_claim_streak(state: DailyRewardState, reward_date) -> int:\n    if state.last_claim_date is None:\n        return 1\n    if state.last_claim_date == reward_date:\n        return int(state.current_streak)\n    if state.last_claim_date == reward_date - timedelta(days=1):\n        return int(state.current_streak) + 1\n    if state.last_claim_date < reward_date - timedelta(days=1):\n        return 1\n    raise ValidationError("Daily reward state contains a future claim date")\n\n\ndef _wallet_claim_block_reason(wallet: TokenWallet | None) -> str:\n    if wallet is None:\n        return ""\n    if wallet.risk_status == LEDGER_RISK_STATUS_BLOCKED:\n        return "Wallet is blocked"\n    if wallet.review_required or wallet.risk_status == LEDGER_RISK_STATUS_REVIEW:\n        return "Wallet is under review"\n    return ""\n\n\ndef _lock_wallet_pair(user_wallet: TokenWallet, issuance_wallet: TokenWallet):\n    ids = sorted({user_wallet.pk, issuance_wallet.pk})\n    locked = {\n        wallet.pk: wallet\n        for wallet in TokenWallet.objects.select_for_update()\n        .filter(pk__in=ids)\n        .order_by("pk")\n    }\n    if len(locked) != 2:\n        raise ValidationError("Could not lock daily reward wallets")\n    return locked[user_wallet.pk], locked[issuance_wallet.pk]\n\n\ndef _build_fixed_transaction_payload(\n    *, user_id, reward_date, streak_day, cycle_day, reward\n):\n    metadata = {\n        "source": "wallet_daily_rewards",\n        "reward_kind": "fixed",\n        "user_id": int(user_id),\n        "reward_date": reward_date.isoformat(),\n        "streak_day": int(streak_day),\n        "cycle_day": int(cycle_day),\n        "cycle_length": len(config.get_daily_reward_definitions()),\n        "amount_tokens": int(reward.amount_tokens),\n        "amount_units": int(reward.amount_units),\n        "asset": reward.asset,\n        "config_version": int(config.DAILY_REWARD_CONFIG_VERSION),\n    }\n    external_id = f"daily-reward:user:{user_id}:date:{reward_date.isoformat()}"\n    payload = {\n        "external_id": external_id,\n        "kind": DAILY_REWARD_TRANSACTION_KIND,\n        "metadata": metadata,\n    }\n    request_hash = hashlib.sha256(\n        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")\n    ).hexdigest()\n    return external_id, request_hash, metadata\n\n\ndef _validate_existing_fixed_transaction(\n    *, txn, user_wallet, issuance_wallet, amount, request_hash\n):\n    if txn.kind != DAILY_REWARD_TRANSACTION_KIND:\n        raise ValidationError(\n            "Daily reward idempotency key belongs to another transaction kind"\n        )\n    if txn.status != LedgerTransaction.STATUS_POSTED:\n        raise ValidationError("Existing daily reward transaction is not posted")\n    if txn.request_hash and txn.request_hash != request_hash:\n        raise ValidationError("Daily reward idempotency payload does not match")\n\n    existing_entries = list(txn.entries.all())\n    if len(existing_entries) != 2:\n        raise ValidationError("Existing daily reward transaction must have two entries")\n    entries = {entry.wallet_id: int(entry.delta) for entry in existing_entries}\n    expected = {\n        user_wallet.pk: int(amount),\n        issuance_wallet.pk: -int(amount),\n    }\n    if entries != expected:\n        raise ValidationError("Existing daily reward ledger entries do not match")\n\n\ndef _create_fixed_daily_reward_ledger_transaction(\n    *, user, user_wallet, issuance_wallet, reward_date, streak_day, cycle_day, reward\n):\n    external_id, request_hash, metadata = _build_fixed_transaction_payload(\n        user_id=user.pk,\n        reward_date=reward_date,\n        streak_day=streak_day,\n        cycle_day=cycle_day,\n        reward=reward,\n    )\n\n    existing = LedgerTransaction.objects.filter(external_id=external_id).first()\n    if existing is not None:\n        _validate_existing_fixed_transaction(\n            txn=existing,\n            user_wallet=user_wallet,\n            issuance_wallet=issuance_wallet,\n            amount=reward.amount_units,\n            request_hash=request_hash,\n        )\n        return existing, metadata\n\n    amount = int(reward.amount_units)\n    user_wallet.balance = int(user_wallet.balance) + amount\n    issuance_wallet.balance = int(issuance_wallet.balance) - amount\n    user_wallet.save(update_fields=["balance", "updated_at"])\n    issuance_wallet.save(update_fields=["balance", "updated_at"])\n\n    txn = LedgerTransaction.objects.create(\n        kind=DAILY_REWARD_TRANSACTION_KIND,\n        status=LedgerTransaction.STATUS_POSTED,\n        external_id=external_id,\n        request_hash=request_hash,\n        created_by=user,\n        memo=f"Daily reward day {cycle_day}",\n        metadata=metadata,\n        metadata_version=LEDGER_METADATA_VERSION,\n    )\n    LedgerEntry.objects.create(\n        txn=txn,\n        wallet=issuance_wallet,\n        delta=-amount,\n        balance_after=issuance_wallet.balance,\n    )\n    LedgerEntry.objects.create(\n        txn=txn,\n        wallet=user_wallet,\n        delta=amount,\n        balance_after=user_wallet.balance,\n    )\n    LedgerOutbox.objects.create(\n        txn=txn,\n        topic=DAILY_REWARD_OUTBOX_TOPIC,\n        aggregate_type="ledger_transaction",\n        aggregate_id=txn.pk,\n        status=LedgerOutbox.STATUS_PENDING,\n        payload={\n            "txn_id": txn.pk,\n            "external_id": external_id,\n            **metadata,\n        },\n        metadata_version=LEDGER_METADATA_VERSION,\n    )\n    return txn, metadata\n\n\ndef _claim_fixed_reward(\n    *, user, reward_date, streak_day, cycle_day, reward\n) -> tuple[LedgerTransaction, dict, None, dict]:\n    user_wallet, _created = TokenWallet.objects.get_or_create(\n        wallet_type=TokenWallet.TYPE_USER,\n        user=user,\n        defaults={"allow_negative": False},\n    )\n    issuance_wallet, _created = TokenWallet.objects.get_or_create(\n        wallet_type=TokenWallet.TYPE_SYSTEM,\n        system_key=TokenWallet.SYSTEM_ISSUANCE,\n        defaults={"allow_negative": True},\n    )\n    if not issuance_wallet.allow_negative:\n        raise ValidationError("System issuance wallet must allow negative balances")\n\n    user_wallet, issuance_wallet = _lock_wallet_pair(user_wallet, issuance_wallet)\n    block_reason = _wallet_claim_block_reason(user_wallet)\n    issuance_block_reason = _wallet_claim_block_reason(issuance_wallet)\n    if block_reason:\n        raise ValidationError(block_reason)\n    if issuance_block_reason:\n        raise ValidationError(\n            f"Daily reward issuance is unavailable: {issuance_block_reason}"\n        )\n\n    txn, metadata = _create_fixed_daily_reward_ledger_transaction(\n        user=user,\n        user_wallet=user_wallet,\n        issuance_wallet=issuance_wallet,\n        reward_date=reward_date,\n        streak_day=streak_day,\n        cycle_day=cycle_day,\n        reward=reward,\n    )\n    result = {\n        "reward_kind": "fixed",\n        "amount_units": int(reward.amount_units),\n        "amount_tokens": int(reward.amount_tokens),\n        "drop_key": "",\n        "drop_label": "",\n        "rarity": "",\n    }\n    return txn, metadata, None, result\n\n\ndef _claim_chest_reward(\n    *, user, reward_date, streak_day, cycle_day, reward\n):\n    source_ref = f"user:{user.pk}:date:{reward_date.isoformat()}"\n    grant = grant_reward_chest(\n        user=user,\n        chest_key=reward.chest_key,\n        source_type="daily_reward",\n        source_ref=source_ref,\n        metadata={\n            "reward_date": reward_date.isoformat(),\n            "streak_day": int(streak_day),\n            "cycle_day": int(cycle_day),\n            "daily_reward_config_version": int(config.DAILY_REWARD_CONFIG_VERSION),\n        },\n    )\n    opened = open_reward_chest(user=user, grant=grant)\n    snapshot = {\n        "source": "wallet_daily_rewards",\n        "reward_kind": "chest",\n        "user_id": int(user.pk),\n        "reward_date": reward_date.isoformat(),\n        "streak_day": int(streak_day),\n        "cycle_day": int(cycle_day),\n        "cycle_length": len(config.get_daily_reward_definitions()),\n        "asset": reward.asset,\n        "chest_key": reward.chest_key,\n        "chest_label": reward.chest_label,\n        "reward_chest_grant_id": grant.pk,\n        "reward_chest_public_id": str(grant.public_id),\n        "amount_tokens": int(opened["amount_tokens"]),\n        "amount_units": int(opened["amount_units"]),\n        "drop_key": opened["drop_key"],\n        "drop_label": opened["drop_label"],\n        "rarity": opened["rarity"],\n        "chance_bps": int(opened["chance_bps"]),\n        "roll": int(opened["roll"]),\n        "daily_reward_config_version": int(config.DAILY_REWARD_CONFIG_VERSION),\n        "reward_chest_config_version": int(grant.config_version),\n        "reward_chest_config_fingerprint": str(\n            grant.config_snapshot.get("fingerprint") or ""\n        ),\n    }\n    LedgerOutbox.objects.create(\n        txn=opened["txn"],\n        topic=DAILY_REWARD_OUTBOX_TOPIC,\n        aggregate_type="ledger_transaction",\n        aggregate_id=opened["txn"].pk,\n        status=LedgerOutbox.STATUS_PENDING,\n        payload={\n            "txn_id": opened["txn"].pk,\n            "external_id": opened["txn"].external_id,\n            **snapshot,\n        },\n        metadata_version=LEDGER_METADATA_VERSION,\n    )\n    result = {\n        "reward_kind": "chest",\n        "amount_units": int(opened["amount_units"]),\n        "amount_tokens": int(opened["amount_tokens"]),\n        "drop_key": opened["drop_key"],\n        "drop_label": opened["drop_label"],\n        "rarity": opened["rarity"],\n    }\n    return opened["txn"], snapshot, grant, result\n\n\ndef _existing_claim_result(existing_claim: DailyRewardClaim, reward_date) -> dict:\n    snapshot = existing_claim.config_snapshot or {}\n    reward_kind = str(snapshot.get("reward_kind") or "fixed")\n    amount_units = int(existing_claim.amount)\n    return {\n        "claimed": False,\n        "already_claimed": True,\n        "claim": existing_claim,\n        "txn": existing_claim.ledger_txn,\n        "reward_chest_grant": existing_claim.reward_chest_grant,\n        "reward_kind": reward_kind,\n        "amount_units": amount_units,\n        "amount_tokens": amount_units // (10 ** config.PLATFORM_TOKEN_DECIMALS),\n        "drop_key": str(snapshot.get("drop_key") or ""),\n        "drop_label": str(snapshot.get("drop_label") or ""),\n        "rarity": str(snapshot.get("rarity") or ""),\n        "streak_day": int(existing_claim.streak_day),\n        "cycle_day": int(existing_claim.cycle_day),\n        "reward_date": reward_date,\n    }\n\n\n@transaction.atomic\ndef claim_daily_reward(*, user, at=None) -> dict:\n    user = _require_eligible_user(user)\n    if not config.DAILY_REWARDS_ENABLED:\n        raise ValidationError("Daily rewards are disabled")\n\n    definitions = config.get_daily_reward_definitions()\n    reward_date = get_daily_reward_date(at)\n\n    user_model = get_user_model()\n    locked_user = user_model.objects.select_for_update().get(pk=user.pk)\n\n    state, _created = DailyRewardState.objects.get_or_create(user=locked_user)\n    state = DailyRewardState.objects.select_for_update().get(pk=state.pk)\n\n    existing_claim = (\n        DailyRewardClaim.objects.select_related(\n            "ledger_txn", "reward_chest_grant"\n        )\n        .filter(user=locked_user, reward_date=reward_date)\n        .first()\n    )\n    if existing_claim is not None:\n        return _existing_claim_result(existing_claim, reward_date)\n\n    streak_day = _calculate_claim_streak(state, reward_date)\n    cycle_day = _get_cycle_day(streak_day, len(definitions))\n    reward = definitions[cycle_day - 1]\n\n    if reward.kind == "fixed":\n        txn, claim_snapshot, chest_grant, reward_result = _claim_fixed_reward(\n            user=locked_user,\n            reward_date=reward_date,\n            streak_day=streak_day,\n            cycle_day=cycle_day,\n            reward=reward,\n        )\n    elif reward.kind == "chest":\n        txn, claim_snapshot, chest_grant, reward_result = _claim_chest_reward(\n            user=locked_user,\n            reward_date=reward_date,\n            streak_day=streak_day,\n            cycle_day=cycle_day,\n            reward=reward,\n        )\n    else:\n        raise ValidationError("Unsupported daily reward kind")\n\n    claim = DailyRewardClaim.objects.create(\n        user=locked_user,\n        reward_date=reward_date,\n        streak_day=streak_day,\n        cycle_day=cycle_day,\n        amount=reward_result["amount_units"],\n        ledger_txn=txn,\n        reward_chest_grant=chest_grant,\n        config_version=config.DAILY_REWARD_CONFIG_VERSION,\n        config_snapshot=claim_snapshot,\n    )\n\n    state.current_streak = streak_day\n    state.last_claim_date = reward_date\n    state.total_claims = int(state.total_claims) + 1\n    state.save(\n        update_fields=[\n            "current_streak",\n            "last_claim_date",\n            "total_claims",\n            "updated_at",\n        ]\n    )\n\n    return {\n        "claimed": True,\n        "already_claimed": False,\n        "claim": claim,\n        "txn": txn,\n        "reward_chest_grant": chest_grant,\n        **reward_result,\n        "streak_day": streak_day,\n        "cycle_day": cycle_day,\n        "reward_date": reward_date,\n    }\n\n\ndef _format_token_amount(amount_tokens: int) -> str:\n    return f"{int(amount_tokens):,}"\n\n\ndef _get_display_streak(\n    state: DailyRewardState | None, reward_date\n) -> tuple[int, bool, bool]:\n    if state is None or state.last_claim_date is None:\n        return 1, False, True\n    if state.last_claim_date == reward_date:\n        return max(1, int(state.current_streak)), True, False\n    if state.last_claim_date == reward_date - timedelta(days=1):\n        return max(1, int(state.current_streak) + 1), False, True\n    if state.last_claim_date < reward_date - timedelta(days=1):\n        return 1, False, True\n    return max(1, int(state.current_streak)), False, False\n\n\ndef _build_reward_row(definition, *, status: str) -> dict:\n    if definition.kind == "fixed":\n        amount_display = _format_token_amount(definition.amount_tokens)\n        claim_label = f"Claim {amount_display}"\n        button_image_path = "images/wallet/cf-token.png"\n        odds = []\n    else:\n        if definition.min_amount_tokens == definition.max_amount_tokens:\n            amount_display = _format_token_amount(definition.min_amount_tokens)\n        else:\n            amount_display = (\n                f"{_format_token_amount(definition.min_amount_tokens)}–"\n                f"{_format_token_amount(definition.max_amount_tokens)}"\n            )\n        claim_label = "Open chest"\n        button_image_path = _ASSET_IMAGE_PATHS[definition.asset]\n        chest = config.get_reward_chest_definition(definition.chest_key)\n        odds = [\n            {\n                "key": drop.key,\n                "label": drop.label,\n                "rarity": drop.rarity,\n                "chance_bps": drop.chance_bps,\n                "chance_percent": drop.chance_bps / 100,\n                "amount_tokens": drop.amount_tokens,\n                "amount_display": _format_token_amount(drop.amount_tokens),\n            }\n            for drop in chest.drops\n        ]\n\n    return {\n        "day": definition.day,\n        "kind": definition.kind,\n        "amount_tokens": definition.amount_tokens,\n        "amount_units": definition.amount_units,\n        "amount_display": amount_display,\n        "asset": definition.asset,\n        "image_path": _ASSET_IMAGE_PATHS[definition.asset],\n        "button_image_path": button_image_path,\n        "claim_label": claim_label,\n        "chest_key": definition.chest_key,\n        "chest_label": definition.chest_label,\n        "min_amount_tokens": definition.min_amount_tokens,\n        "max_amount_tokens": definition.max_amount_tokens,\n        "odds": odds,\n        "status": status,\n    }\n\n\ndef build_daily_rewards_context(*, user, claim_url: str, at=None) -> dict:\n    definitions = config.get_daily_reward_definitions()\n    reward_date = get_daily_reward_date(at)\n    state = DailyRewardState.objects.filter(user=user).first()\n    display_streak, claimed_today, date_allows_claim = _get_display_streak(\n        state, reward_date\n    )\n    cycle_day = _get_cycle_day(display_streak, len(definitions))\n    current_reward = definitions[cycle_day - 1]\n\n    wallet = TokenWallet.objects.filter(\n        wallet_type=TokenWallet.TYPE_USER,\n        user=user,\n    ).first()\n    issuance_wallet = TokenWallet.objects.filter(\n        wallet_type=TokenWallet.TYPE_SYSTEM,\n        system_key=TokenWallet.SYSTEM_ISSUANCE,\n    ).first()\n    block_reason = _wallet_claim_block_reason(wallet)\n    issuance_block_reason = _wallet_claim_block_reason(issuance_wallet)\n    if not block_reason and issuance_block_reason:\n        block_reason = "Daily reward issuance is unavailable"\n    can_claim = bool(\n        config.DAILY_REWARDS_ENABLED\n        and getattr(user, "is_active", False)\n        and date_allows_claim\n        and not claimed_today\n        and not block_reason\n    )\n\n    window_size = int(config.DAILY_REWARD_WINDOW_SIZE)\n    start_day = max(\n        1,\n        min(\n            cycle_day - (window_size // 2),\n            len(definitions) - window_size + 1,\n        ),\n    )\n    end_day = start_day + window_size - 1\n\n    def status_for(day):\n        if day == cycle_day:\n            return "current"\n        if day < cycle_day:\n            return "claimed"\n        return "future"\n\n    window = [\n        _build_reward_row(definitions[day - 1], status=status_for(day))\n        for day in range(start_day, end_day + 1)\n    ]\n    all_rewards = [\n        _build_reward_row(definition, status=status_for(definition.day))\n        for definition in definitions\n    ]\n    current_position = cycle_day - start_day\n    timeline_percent = 0\n    if window_size > 1:\n        timeline_percent = round(\n            (current_position / (window_size - 1)) * 90,\n            2,\n        )\n\n    return {\n        "enabled": bool(config.DAILY_REWARDS_ENABLED),\n        "claim_url": claim_url,\n        "reward_date": reward_date,\n        "timezone": str(get_daily_reward_timezone()),\n        "next_reset_at": get_next_daily_reward_reset(at),\n        "streak": display_streak,\n        "cycle_day": cycle_day,\n        "cycle_length": len(definitions),\n        "claimed_today": claimed_today,\n        "can_claim": can_claim,\n        "block_reason": block_reason,\n        "current_reward": _build_reward_row(current_reward, status="current"),\n        "window": window,\n        "all_rewards": all_rewards,\n        "timeline_percent": timeline_percent,\n    }\n')

replace_file('ledger/dashboard/views.py', '6b20fd1d9c7182a70b47b61d71752eb07c86c470', 'from django.contrib import messages\nfrom django.contrib.auth.decorators import login_required\nfrom django.core.exceptions import PermissionDenied, ValidationError\nfrom django.shortcuts import redirect\nfrom django.views.decorators.http import require_POST\n\nfrom .daily_rewards import claim_daily_reward\n\n\n@login_required\n@require_POST\ndef wallet_claim_daily_reward(request):\n    try:\n        result = claim_daily_reward(user=request.user)\n    except (PermissionDenied, ValidationError) as exc:\n        messages.error(\n            request,\n            exc.messages[0] if hasattr(exc, "messages") else str(exc),\n        )\n        return redirect("wallet")\n\n    if result["claimed"] and result["reward_kind"] == "chest":\n        messages.success(\n            request,\n            f"Reward Chest opened: {result[\'amount_tokens\']:,} tokens.",\n        )\n    elif result["claimed"]:\n        messages.success(request, "Daily reward claimed.")\n    else:\n        messages.info(request, "Today\'s daily reward was already claimed.")\n    return redirect("wallet")\n')

write_new('ledger/dashboard/reward_chests.py', 'from __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nimport secrets\n\nfrom django.contrib.auth import get_user_model\nfrom django.core.exceptions import PermissionDenied, ValidationError\nfrom django.db import IntegrityError, transaction\nfrom django.utils import timezone\n\nfrom ledger.models import (\n    LEDGER_METADATA_VERSION,\n    LEDGER_RISK_STATUS_BLOCKED,\n    LEDGER_RISK_STATUS_REVIEW,\n    LedgerEntry,\n    LedgerOutbox,\n    LedgerTransaction,\n    TokenWallet,\n)\n\nfrom . import config\nfrom .models import RewardChestGrant\n\n\nREWARD_CHEST_TRANSACTION_KIND = "reward_chest"\nREWARD_CHEST_OUTBOX_TOPIC = "ledger.reward_chest.opened"\n_SOURCE_TYPE_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,31}$")\n\n\ndef _require_eligible_user(user):\n    if not getattr(user, "is_authenticated", False):\n        raise PermissionDenied("Authentication is required")\n    if not getattr(user, "pk", None):\n        raise PermissionDenied("A persisted user account is required")\n    if not getattr(user, "is_active", False):\n        raise PermissionDenied("Inactive accounts cannot receive Reward Chests")\n    return user\n\n\ndef _normalize_source_type(value: str) -> str:\n    normalized = str(value or "").strip().lower()\n    if not _SOURCE_TYPE_RE.fullmatch(normalized):\n        raise ValidationError(\n            "Reward Chest source type must use lowercase letters, digits, underscores, or hyphens"\n        )\n    return normalized\n\n\ndef _normalize_source_ref(value: str) -> str:\n    normalized = str(value or "").strip()\n    if not normalized:\n        raise ValidationError("Reward Chest source reference is required")\n    if len(normalized) > 160:\n        raise ValidationError("Reward Chest source reference is too long")\n    return normalized\n\n\ndef _normalize_metadata(metadata) -> dict:\n    if metadata is None:\n        return {}\n    if not isinstance(metadata, dict):\n        raise ValidationError("Reward Chest metadata must be a dictionary")\n    return dict(metadata)\n\n\ndef _wallet_open_block_reason(wallet: TokenWallet | None) -> str:\n    if wallet is None:\n        return ""\n    if wallet.risk_status == LEDGER_RISK_STATUS_BLOCKED:\n        return "Wallet is blocked"\n    if wallet.review_required or wallet.risk_status == LEDGER_RISK_STATUS_REVIEW:\n        return "Wallet is under review"\n    return ""\n\n\ndef _lock_wallet_pair(user_wallet: TokenWallet, issuance_wallet: TokenWallet):\n    ids = sorted({user_wallet.pk, issuance_wallet.pk})\n    locked = {\n        wallet.pk: wallet\n        for wallet in TokenWallet.objects.select_for_update()\n        .filter(pk__in=ids)\n        .order_by("pk")\n    }\n    if len(locked) != 2:\n        raise ValidationError("Could not lock Reward Chest wallets")\n    return locked[user_wallet.pk], locked[issuance_wallet.pk]\n\n\ndef _validate_existing_grant(\n    *, grant: RewardChestGrant, user_id: int, chest_key: str\n) -> RewardChestGrant:\n    if grant.user_id != int(user_id):\n        raise ValidationError("Reward Chest source reference already belongs to another user")\n    if grant.chest_key != chest_key:\n        raise ValidationError("Reward Chest source reference was reused for another chest")\n    return grant\n\n\n@transaction.atomic\ndef grant_reward_chest(\n    *,\n    user,\n    chest_key: str,\n    source_type: str,\n    source_ref: str,\n    metadata=None,\n    expires_at=None,\n) -> RewardChestGrant:\n    """Create one immutable, idempotent Reward Chest entitlement.\n\n    ``source_type`` + ``source_ref`` is the business idempotency key. The\n    snapshot is captured when the grant is created, so later config edits do\n    not change an already granted chest.\n    """\n\n    user = _require_eligible_user(user)\n    definition = config.get_reward_chest_definition(chest_key)\n    source_type = _normalize_source_type(source_type)\n    source_ref = _normalize_source_ref(source_ref)\n    metadata = _normalize_metadata(metadata)\n\n    now = timezone.now()\n    if expires_at is not None:\n        if timezone.is_naive(expires_at):\n            raise ValidationError("Reward Chest expiry must be timezone-aware")\n        if expires_at <= now:\n            raise ValidationError("Reward Chest expiry must be in the future")\n\n    user_model = get_user_model()\n    locked_user = user_model.objects.select_for_update().get(pk=user.pk)\n\n    existing = (\n        RewardChestGrant.objects.select_for_update()\n        .filter(source_type=source_type, source_ref=source_ref)\n        .first()\n    )\n    if existing is not None:\n        return _validate_existing_grant(\n            grant=existing,\n            user_id=locked_user.pk,\n            chest_key=definition.key,\n        )\n\n    snapshot = config.build_reward_chest_snapshot(definition)\n    try:\n        with transaction.atomic():\n            return RewardChestGrant.objects.create(\n                user=locked_user,\n                chest_key=definition.key,\n                source_type=source_type,\n                source_ref=source_ref,\n                status=RewardChestGrant.STATUS_PENDING,\n                config_version=config.REWARD_CHEST_CONFIG_VERSION,\n                config_snapshot=snapshot,\n                metadata=metadata,\n                expires_at=expires_at,\n            )\n    except IntegrityError:\n        existing = RewardChestGrant.objects.select_for_update().get(\n            source_type=source_type,\n            source_ref=source_ref,\n        )\n        return _validate_existing_grant(\n            grant=existing,\n            user_id=locked_user.pk,\n            chest_key=definition.key,\n        )\n\n\ndef _select_drop(definition: config.RewardChestDefinition):\n    roll = secrets.randbelow(config.REWARD_CHEST_TOTAL_CHANCE_BPS)\n    for drop in definition.drops:\n        if roll < drop.cumulative_end_bps:\n            return roll, drop\n    raise ValidationError("Reward Chest drop table did not resolve the roll")\n\n\ndef _build_transaction_payload(\n    *,\n    grant: RewardChestGrant,\n    definition: config.RewardChestDefinition,\n    roll: int,\n    drop: config.RewardChestDropDefinition,\n) -> tuple[str, str, dict]:\n    external_id = f"reward-chest:grant:{grant.public_id}"\n    metadata = {\n        "source": "reward_chest",\n        "reward_chest_grant_id": grant.pk,\n        "reward_chest_public_id": str(grant.public_id),\n        "user_id": grant.user_id,\n        "chest_key": definition.key,\n        "chest_label": definition.label,\n        "source_type": grant.source_type,\n        "source_ref": grant.source_ref,\n        "roll": int(roll),\n        "drop_key": drop.key,\n        "drop_label": drop.label,\n        "rarity": drop.rarity,\n        "chance_bps": int(drop.chance_bps),\n        "amount_tokens": int(drop.amount_tokens),\n        "amount_units": int(drop.amount_units),\n        "config_version": int(grant.config_version),\n        "config_fingerprint": str(grant.config_snapshot.get("fingerprint") or ""),\n    }\n    payload = {\n        "external_id": external_id,\n        "kind": REWARD_CHEST_TRANSACTION_KIND,\n        "metadata": metadata,\n    }\n    request_hash = hashlib.sha256(\n        json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode(\n            "utf-8"\n        )\n    ).hexdigest()\n    return external_id, request_hash, metadata\n\n\ndef _opened_result(grant: RewardChestGrant) -> dict:\n    if (\n        grant.status != RewardChestGrant.STATUS_OPENED\n        or grant.ledger_txn_id is None\n        or grant.amount is None\n        or grant.roll is None\n        or not grant.drop_key\n    ):\n        raise ValidationError("Reward Chest opened state is incomplete")\n    return {\n        "opened": False,\n        "already_opened": True,\n        "grant": grant,\n        "txn": grant.ledger_txn,\n        "roll": int(grant.roll),\n        "drop_key": grant.drop_key,\n        "drop_label": grant.drop_label,\n        "rarity": grant.rarity,\n        "chance_bps": int(grant.chance_bps or 0),\n        "amount_units": int(grant.amount),\n        "amount_tokens": int(grant.amount) // (10 ** config.PLATFORM_TOKEN_DECIMALS),\n    }\n\n\n@transaction.atomic\ndef open_reward_chest(*, user, grant, at=None) -> dict:\n    """Open a granted chest exactly once and credit the selected token drop."""\n\n    user = _require_eligible_user(user)\n    grant_id = grant.pk if isinstance(grant, RewardChestGrant) else int(grant)\n    locked_grant = (\n        RewardChestGrant.objects.select_for_update()\n        .select_related("ledger_txn")\n        .get(pk=grant_id)\n    )\n\n    if locked_grant.user_id != user.pk:\n        raise PermissionDenied("Cannot open another user\'s Reward Chest")\n    if locked_grant.status == RewardChestGrant.STATUS_OPENED:\n        return _opened_result(locked_grant)\n    if locked_grant.status == RewardChestGrant.STATUS_REVOKED:\n        raise ValidationError("Reward Chest has been revoked")\n    if locked_grant.status != RewardChestGrant.STATUS_PENDING:\n        raise ValidationError("Reward Chest is not openable")\n\n    now = at or timezone.now()\n    if timezone.is_naive(now):\n        raise ValidationError("Reward Chest open time must be timezone-aware")\n    if locked_grant.expires_at is not None and locked_grant.expires_at <= now:\n        raise ValidationError("Reward Chest has expired")\n\n    definition = config.reward_chest_definition_from_snapshot(\n        locked_grant.config_snapshot\n    )\n    if definition.key != locked_grant.chest_key:\n        raise ValidationError("Reward Chest snapshot key does not match the grant")\n\n    user_wallet, _created = TokenWallet.objects.get_or_create(\n        wallet_type=TokenWallet.TYPE_USER,\n        user_id=locked_grant.user_id,\n        defaults={"allow_negative": False},\n    )\n    issuance_wallet, _created = TokenWallet.objects.get_or_create(\n        wallet_type=TokenWallet.TYPE_SYSTEM,\n        system_key=TokenWallet.SYSTEM_ISSUANCE,\n        defaults={"allow_negative": True},\n    )\n    if not issuance_wallet.allow_negative:\n        raise ValidationError("System issuance wallet must allow negative balances")\n\n    user_wallet, issuance_wallet = _lock_wallet_pair(user_wallet, issuance_wallet)\n    user_block_reason = _wallet_open_block_reason(user_wallet)\n    issuance_block_reason = _wallet_open_block_reason(issuance_wallet)\n    if user_block_reason:\n        raise ValidationError(user_block_reason)\n    if issuance_block_reason:\n        raise ValidationError(\n            f"Reward Chest issuance is unavailable: {issuance_block_reason}"\n        )\n\n    roll, drop = _select_drop(definition)\n    amount = int(drop.amount_units)\n    external_id, request_hash, txn_metadata = _build_transaction_payload(\n        grant=locked_grant,\n        definition=definition,\n        roll=roll,\n        drop=drop,\n    )\n\n    if LedgerTransaction.objects.filter(external_id=external_id).exists():\n        raise ValidationError("Reward Chest ledger transaction exists but grant is not opened")\n\n    user_wallet.balance = int(user_wallet.balance) + amount\n    issuance_wallet.balance = int(issuance_wallet.balance) - amount\n    user_wallet.save(update_fields=["balance", "updated_at"])\n    issuance_wallet.save(update_fields=["balance", "updated_at"])\n\n    txn = LedgerTransaction.objects.create(\n        kind=REWARD_CHEST_TRANSACTION_KIND,\n        status=LedgerTransaction.STATUS_POSTED,\n        external_id=external_id,\n        request_hash=request_hash,\n        created_by_id=locked_grant.user_id,\n        memo=f"{definition.label} opened",\n        metadata=txn_metadata,\n        metadata_version=LEDGER_METADATA_VERSION,\n    )\n    LedgerEntry.objects.create(\n        txn=txn,\n        wallet=issuance_wallet,\n        delta=-amount,\n        balance_after=issuance_wallet.balance,\n    )\n    LedgerEntry.objects.create(\n        txn=txn,\n        wallet=user_wallet,\n        delta=amount,\n        balance_after=user_wallet.balance,\n    )\n    LedgerOutbox.objects.create(\n        txn=txn,\n        topic=REWARD_CHEST_OUTBOX_TOPIC,\n        aggregate_type="reward_chest_grant",\n        aggregate_id=locked_grant.pk,\n        status=LedgerOutbox.STATUS_PENDING,\n        payload={\n            "txn_id": txn.pk,\n            "external_id": external_id,\n            **txn_metadata,\n        },\n        metadata_version=LEDGER_METADATA_VERSION,\n    )\n\n    locked_grant.status = RewardChestGrant.STATUS_OPENED\n    locked_grant.roll = roll\n    locked_grant.drop_key = drop.key\n    locked_grant.drop_label = drop.label\n    locked_grant.rarity = drop.rarity\n    locked_grant.chance_bps = drop.chance_bps\n    locked_grant.amount = amount\n    locked_grant.ledger_txn = txn\n    locked_grant.opened_at = now\n    locked_grant.save(\n        update_fields=[\n            "status",\n            "roll",\n            "drop_key",\n            "drop_label",\n            "rarity",\n            "chance_bps",\n            "amount",\n            "ledger_txn",\n            "opened_at",\n        ]\n    )\n\n    return {\n        "opened": True,\n        "already_opened": False,\n        "grant": locked_grant,\n        "txn": txn,\n        "roll": roll,\n        "drop_key": drop.key,\n        "drop_label": drop.label,\n        "rarity": drop.rarity,\n        "chance_bps": drop.chance_bps,\n        "amount_units": amount,\n        "amount_tokens": drop.amount_tokens,\n    }\n')

